queue = []

def enqueue():
    queue.append(input("Enter shuttlecock ID to add: "))
    print("Shuttlecock added to the box.")

def dequeue():
    if not queue:
        print("Box is empty. Underflow!")
    else:
        print("Removed shuttlecock:", queue.pop(0))

def display():
    print("Shuttlecocks in box (front to rear):", queue)

while True:
    print("\n1. Add shuttlecock (enqueue)\n2. Remove shuttlecock (dequeue)\n3. Display\n4. Exit")
    choice = int(input("Enter choice: "))
    if choice == 1:
        enqueue()
    elif choice == 2:
        dequeue()
    elif choice == 3:
        display()
    elif choice == 4:
        break
    else:
        print("Invalid choice")

from collections import deque

def is_palindrome(s):
    dq = deque(s)
    while len(dq) > 1:
        front = dq.popleft()
        rear = dq.pop()
        if front != rear:
            return False
    return True

text = input("Enter a string: ")
if is_palindrome(text):
    print(text, "is a palindrome")
else:
    print(text, "is not a palindrome")

def bubble_sort(lst):
    n = len(lst)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if lst[j] > lst[j + 1]:
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst

def find_median(lst):
    lst = bubble_sort(lst)
    n = len(lst)
    mid = n // 2
    if n % 2 == 1:
        return lst[mid]
    else:
        return (lst[mid - 1] + lst[mid]) / 2

numbers = list(map(int, input("Enter numbers separated by space: ").split()))
print("Median:", find_median(numbers))

def linear_search(lst, key):
    for i in range(len(lst)):
        if lst[i] == key:
            return i
    return -1

numbers = list(map(int, input("Enter 10 numbers (mix of positive/negative): ").split()))
key = int(input("Enter the key to search: "))
pos = linear_search(numbers, key)
if pos != -1:
    print(f"{key} found at position {pos}")
else:
    print(f"{key} not found in the list")

def binary_search(lst, key):
    low, high = 0, len(lst) - 1
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == key:
            return mid
        elif lst[mid] < key:
            low = mid + 1
        else:
            high = mid - 1
    return -1

numbers = list(map(int, input("Enter 10 integers in ascending order: ").split()))
key = int(input("Enter the key to search: "))
pos = binary_search(numbers, key)
if pos != -1:
    print(f"{key} found at position {pos}")
else:
    print(f"{key} not found in the list")

words = ["Perfect","Stupendous","Wondrous","Gorgeous","Awesome","Splendid","Fabulous","Mirthful","Incredible","Outstanding","Propitious","Remarkable","Stellar","Unbelievable","Super","Amazing"]

def linear_search(lst, key):
    comparisons = 0
    for i in range(len(lst)):
        comparisons += 1
        if lst[i] == key:
            return i, comparisons
    return -1, comparisons

def binary_search(lst, key):
    low, high, iterations = 0, len(lst) - 1, 0
    while low <= high:
        iterations += 1
        mid = (low + high) // 2
        if lst[mid] == key:
            return mid, iterations
        elif lst[mid] < key:
            low = mid + 1
        else:
            high = mid - 1
    return -1, iterations

keys = ["Amazing", "Perfect", "Great", "Wondrous"]
for k in keys:
    pos, comps = linear_search(words, k)
    print(k, "-> linear search on unsorted list: position", pos, "comparisons", comps)

words.sort()
for k in keys:
    pos, comps = linear_search(words, k)
    print(k, "-> linear search on sorted list: position", pos, "comparisons", comps)

for k in keys:
    pos, iters = binary_search(words, k)
    print(k, "-> binary search: position", pos, "iterations", iters)

